from pathlib import Path
import base64,html
out=Path(__file__).resolve().parent
features=[
('01','经营驾驶舱','用同一张工作台，把业务全貌看清楚。','按时间和角色范围查看客户、商机、合同和回款；主管包含下属团队，老板掌握公司全貌，统计可下钻并切换正反序。','01-dashboard.jpg','期间经营 · 人员范围 · 明细下钻'),
('02','客户经营','把公共资源，变成持续经营的客户关系。','客户档案连接联系人、商机、合同、项目与跟进。公海、私海、分配和重复提示共同服务客户经营。','03-customer.jpg','客户归属 · 联系人 · 跟进 · 客户分配'),
('03','商机与报价','标准件和定制件，都有清晰的推进过程。','看板直接显示客户与跟进入口，把技术要求、报价版本和下一步行动记录在同一条业务链路中，围绕阶段持续推进。','02-pipeline.jpg','线索转化 · 产品报价 · 阶段推进'),
('04','合同与审批','供货条件有据可查，处理过程有迹可循。','合同关联客户、签约主体、供货明细和付款条件。审批中心保留申请版本与节点处理，支持或签等协作方式。','04-contract.jpg','合同台账 · 审批节点 · 版本留痕'),
('05','项目与交付协作','销售承诺，接得住，也跟得下去。','需求图纸、供货方案、检验资料和现场验收按里程碑组织。项目负责人、销售和技术人员围绕任务与证据协作。','05-project.jpg','技术确认 · 里程碑 · 任务 · 证据附件'),
('06','收款与应收','看清每一期计划，也看清每一笔到账。','按首付、发货、验收和质保节点管理回款计划，连接开票记录、收款登记、独立复核、预收核销和处理历史。','06-ledger.jpg','分期应收 · 独立复核 · 预收核销'),
('07','合同与收款统计','把合同、开票和回款，放到同一口径里核对。','合同总金额、已收款、待收款，以及开票已收、开票待收和在建金额逐项展示；预计收款安排写明日期、金额和依据。渠道服务与软件返佣分别统计。','07-forecast.jpg','合同批次 · 逐笔回款 · 渠道往来'),
('08','漏斗与复盘','数字点得开，原因说得清。','从销售阶段下钻具体客户与机会。将成交、在途和掉单分开复盘，记录竞争、资源窗口等原因，为下一轮经营提供依据。','08-funnel.jpg','漏斗统计 · 掉单原因 · 业务明细'),
('09','AI 原生协同','让智能体接入业务，让人员掌握执行。','按授权查询客户与经营数据，预演下一步行动；人员核对批准后执行，保留处理意见、执行结果与业务行动记录。','09-ai-actions.jpg','权限内调用 · 人工核对 · 执行回执')]
sections=[]
for no,title,lead,body,photo,tags in features:
 data=base64.b64encode((out/'screenshots'/photo).read_bytes()).decode()
 sections.append(f'''<section class="feature" id="f{no}"><div class="copy"><div class="kicker">{no} / {title}</div><h2>{lead}</h2><p>{body}</p><span class="tags">{tags}</span></div><button class="screen" aria-label="放大查看：{title}" data-caption="{title}"><img src="data:image/jpeg;base64,{data}" alt="天雨阀门：{title}实际系统画面" loading="lazy"><span>实际业务画面 · 点击放大 ↗</span></button></section>''')
